import{_ as t,o as i,c as g,a5 as h}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-2-platform-statistics-overview/report3_spec.md","filePath":"feature/admin-management/3-10-2-platform-statistics-overview/report3_spec.md"}'),o={name:"feature/admin-management/3-10-2-platform-statistics-overview/report3_spec.md"};function r(s,n,l,e,c,u){return i(),g("div",null,[...n[0]||(n[0]=[h("<p><strong>3.10.2 Platform Statistics Overview (Thống Kê Tổng Quan Nền Tảng)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) truy cập trang chủ quản trị tại route /admin/dashboard.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên theo dõi hiệu suất vận hành, người dùng và doanh thu nền tảng.</li><li><strong>Purpose</strong>: Hiển thị hoạt động đăng nhập thành công, tăng trưởng người dùng, tài khoản FLAGGED, strike còn hiệu lực và chỉ số tài chính có định nghĩa rõ.</li><li><strong>Interface</strong>: Bảng điều khiển Thống kê Tổng quan (SCR-ADM-02), gồm 4 thẻ KPI, biểu đồ tăng trưởng người dùng, biểu đồ doanh thu và bảng top agency.</li><li><strong>Data Processing</strong>: Kiểm tra ADMIN; tổng hợp sự kiện đăng nhập, số bài/hoạt động, trạng thái strike còn hiệu lực và thanh toán đối soát. Cache tối đa 15 phút theo bộ lọc, múi giờ và tiêu chí xếp hạng; trả asOf và biên kỳ.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Bảng điều khiển Thống kê Tổng quan Nền tảng (SCR-ADM-02):</p><ul><li>Left/Header: Điều hướng Admin, bộ lọc kỳ và chọn múi giờ UTC / Asia/Ho_Chi_Minh (mặc định).</li><li>Center: KPI: tổng user / user đăng nhập thành công trong 30 ngày gần nhất, user FLAGGED, strike YELLOW/ORANGE/RED còn hiệu lực, tiền thu gộp. Biểu đồ tăng trưởng, tiền thu và phân bố gói; Top 5 Agency chọn xếp riêng theo số bài, hoạt động nghiệp vụ, doanh thu. Hiển thị tiêu chí và kỳ của bảng xếp hạng.</li><li>Buttons: Nút &quot;Làm mới dữ liệu&quot; (xóa cache Redis và tải lại), Nút chọn &quot;Khoảng ngày tùy chỉnh&quot;, Nút &quot;Xuất Báo cáo PDF&quot;.</li><li>Footer: Thời điểm đồng bộ, múi giờ đã chọn và chỉ báo dữ liệu cũ/lỗi.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Không có (mặc định hiển thị 12 tháng gần nhất).</li><li><strong>Input optional</strong>: period, startDate, endDate, timezone (UTC hoặc Asia/Ho_Chi_Minh), agencyRankBy (POSTS, ACTIVITY, REVENUE).</li><li><strong>System data</strong>: totalUsers, activeUsers30d, flaggedUsersCount, activeStrikeCounts, grossReceipts, refunds, netReceipts, topAgencies, asOf, timezone.</li><li><strong>Output</strong>: Gói dữ liệu JSON thống kê tổng quan nền tảng, mã HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Thống kê toàn nền tảng chỉ dành cho ADMIN.</li><li><strong>BR-65</strong>: activeUsers30d đếm user khác nhau có đăng nhập thành công trong 30 ngày gần nhất. Đăng nhập lỗi hoặc chỉ refresh token không được tính.</li><li><strong>BR-65</strong>: Có đủ ba kiểu xếp hạng Agency theo số bài, số hoạt động nghiệp vụ và doanh thu trong kỳ; không tự đặt điểm tổng hợp có trọng số. Plan kỹ thuật phải ánh xạ rõ nguồn bài viết, sự kiện hoạt động và cách quy thuộc thanh toán hiện có.</li><li><strong>BR-94</strong>: Bộ đếm strike dùng điều kiện còn hiệu lực và thời gian sạch tại FR 3.10.5, không lọc createdAt &gt;= now−30 ngày. Lịch sử đã quy đổi/gỡ/hết hạn hiển thị riêng.</li><li><strong>BR-60</strong>: MRR là giá trị thuê bao trả phí đang hiệu lực quy về tháng sau giảm giá áp dụng; gói năm đóng góp giá năm / 12. ARR = MRR × 12. Tiền thu gộp gồm thanh toán subscription và AI Credit mua lẻ thành công trong kỳ. Hiển thị tiền hoàn riêng; thu ròng = tiền thu gộp − tiền hoàn. AI Credit không vào MRR. Hoàn tiền chỉ đổi MRR khi giá trị/trạng thái thuê bao thay đổi; không trừ hai lần.</li><li><strong>BR-65</strong>: Lưu thời điểm bằng UTC; báo cáo cho chọn UTC hoặc Asia/Ho_Chi_Minh (mặc định). Tính biên ngày và nhóm ngày/tháng theo múi giờ đã chọn; trả múi giờ trong response, bản xuất và khóa cache.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Người dùng không có quyền ADMIN → Display: MSG39</li><li>Khoảng ngày tùy chỉnh không có dữ liệu → Display: MSG122</li><li>Vượt quá tần suất yêu cầu làm mới dữ liệu → Display: MSG48</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin mở SCR-ADM-02; hệ thống kiểm tra quyền ADMIN.</li><li>Chọn kỳ, múi giờ và một trong ba tiêu chí xếp hạng Agency.</li><li>Trả tổng hợp từ cache còn hạn hoặc tính theo cùng bộ lọc và biên múi giờ.</li><li>Hiển thị KPI, biểu đồ, xếp hạng và asOf; giữ bộ lọc khi xuất PDF.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Nếu người dùng không có vai trò ADMIN, hệ thống chặn truy cập và hiển thị MSG39.</li><li>5.a1: Nếu khoảng ngày chọn không có dữ liệu phát sinh, hệ thống hiển thị MSG122.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Dữ liệu thống kê được hiển thị trực quan trên giao diện Admin.</li><li>Dữ liệu tính toán mới được lưu vào Redis cache với TTL 15 phút.</li></ul>",14)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
